// File: rad-proxy-4/RadCollectionNft.sol


pragma solidity ^0.8.26;







contract RadCollectionNftContract is 
    Initializable, 
    ERC1155Upgradeable, 
    OwnableUpgradeable, 
    UUPSUpgradeable, 
    ERC1155SupplyUpgradeable,
    IERC2981Upgradeable 
{
    struct RevenueSplit {
        address wallet;
        uint256 percentange; // 22 = 2.2%
        string nickname;
    }
    struct NftDetailStruct {
        address createdBy;
        bool status;
        uint256 mintPrice;
        uint256 maxSupply;
    }

    uint256 public totalNFTs;
    string public contractName;
    string public contractMetadataURI;
    mapping(uint256 => string) public UriOf;
    mapping(uint256 => NftDetailStruct) public nftDetailOf;
    mapping(uint256 => uint256) public currentSupplyOf;
    mapping(uint256 => RevenueSplit[]) public revenueSplitsOfNFT;
    mapping(uint256 => RevenueSplit) public secondaryRoyaltiesOfNFT;

    uint256 platformCommisionPercentage;
    uint256 platformResaleCommissionPercentage;
    address platformAddress;

    event NFTcreated(uint256 indexed id, uint256 mintPrice, uint256 time);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address initialOwner,
        string memory _contractName,
        string memory _contractMetadataURI
    ) public initializer {
        __ERC1155_init("Rad Collection");
        __Ownable_init();
        __UUPSUpgradeable_init();
        __ERC1155Supply_init();

        contractName = _contractName;
        contractMetadataURI = _contractMetadataURI;
        totalNFTs = 0;
        platformCommisionPercentage = 300; // 30%
        platformResaleCommissionPercentage = 30; // 3%
        platformAddress = 0x02232a2de6C1d673D19ee48f556A3933AC987eCc; // Default platform address

        transferOwnership(initialOwner);
    }

    function _authorizeUpgrade(address newImplementation)
        internal
        override
        onlyOwner
    {}

    function name() public view returns (string memory) {
        return contractName;
    }

    function contractURI() public view returns (string memory) {
        return contractMetadataURI;
    }

    function symbol() public pure returns (string memory) {
        return "RAD";
    }

    modifier onlyNftExist(uint256 id) {
        require(totalNFTs >= id, "NFT does not exist");
        _;
    }

    modifier onlyNftCreator(uint256 id) {
        require(
            nftDetailOf[id].createdBy == msg.sender,
            "Only the creator can perform this action"
        );
        _;
    }

    modifier onlyPlatform() {
        require(
            msg.sender == platformAddress,
            "Only platform can call this function"
        );
        _;
    }

    function createNFT(
        string memory _nftUri,
        uint256 _mintPrice,
        uint256 _maxSupply,
        RevenueSplit[] memory revenueSplits,
        RevenueSplit memory secondaryRoyalty
    ) public returns (uint256) {
        // Check revenue splits percentage
        _checkPercentage(revenueSplits);
        require(secondaryRoyalty.percentange <= 1000, "Secondary royalty percentage too high");

        uint256 _nftId = totalNFTs + 1;

        // Add NFT details
        nftDetailOf[_nftId] = NftDetailStruct(
            msg.sender,
            true,
            _mintPrice,
            _maxSupply
        );
        UriOf[_nftId] = _nftUri;
        emit NFTcreated(_nftId, _mintPrice, block.timestamp);

        // Add revenue splits and secondary royalty
        _addRevenueSplitOfToken(_nftId, revenueSplits);
        
        // Store single secondary royalty
        secondaryRoyaltiesOfNFT[_nftId] = RevenueSplit(
            secondaryRoyalty.wallet,
            secondaryRoyalty.percentange,
            secondaryRoyalty.nickname
        );

        totalNFTs++;
        return _nftId;
    }

    
    function updateURIOfToken(
        uint256 id,
        string memory tokenUri
    ) public onlyNftCreator(id) onlyNftExist(id) {
        UriOf[id] = tokenUri;
    }

    function updateNftDetails(
        uint256 id,
        NftDetailStruct memory _details
    ) public onlyNftCreator(id) onlyNftExist(id) {
        nftDetailOf[id] = _details;
    }

    function updateMintPrice(uint256 id, uint256 newPrice) public onlyNftCreator(id) onlyNftExist(id) {
        nftDetailOf[id].mintPrice = newPrice;
    }

    function updateRevenueSplitOfToken(
        uint256 _nftId,
        RevenueSplit[] memory revenueSplits
    ) public onlyNftCreator(_nftId) onlyNftExist(_nftId) {
        _checkPercentage(revenueSplits);
        _addRevenueSplitOfToken(_nftId, revenueSplits);
    }

    function getRevenueSplitsOfToken(
        uint256 _nftId
    ) public view returns (RevenueSplit[] memory) {
        return revenueSplitsOfNFT[_nftId];
    }

    function mint(
        address account,
        uint256 id,
        uint256 amount
    ) public payable onlyNftExist(id) {
        require(
            msg.value >= nftDetailOf[id].mintPrice * amount,
            "Please send the full mint price for all tokens"
        );

        if (nftDetailOf[id].maxSupply != 0) {
            require(
                currentSupplyOf[id] + amount <= nftDetailOf[id].maxSupply,
                "Max supply exceeds for this NFT"
            );
        }

        _mint(account, id, amount, "");
        currentSupplyOf[id] += amount;
        splitRevenue(id, nftDetailOf[id].mintPrice * amount);
    }

    function splitRevenue(uint256 nftid, uint256 totalAmount) private {
        uint256 platformCommissionAmount = (totalAmount * platformCommisionPercentage) / 1000;
        (bool sent, ) = platformAddress.call{value: platformCommissionAmount}("");
        require(sent, "Failed to send payment to platform");

        uint256 remainingAmount = totalAmount - platformCommissionAmount;
        RevenueSplit[] memory revenueSplits = revenueSplitsOfNFT[nftid];
        _checkPercentage(revenueSplits);

        // Distribute the remaining amount to each revenue split
        for (uint i = 0; i < revenueSplits.length; i++) {
            RevenueSplit memory oneUserSplit = revenueSplits[i];
            uint256 userAmount = (remainingAmount * oneUserSplit.percentange) / 1000;
            (bool sentOther, ) = oneUserSplit.wallet.call{value: userAmount}("");
            require(sentOther, "Failed to send payment to account");
        }
    }

    function uri(
        uint256 id
    ) public view virtual override returns (string memory) {
        return UriOf[id];
    }

    function transferEth(address _to, uint256 amount) public onlyPlatform {
        (bool sent, ) = _to.call{value: amount}("");
        require(sent, "Failed to send Ether");
    }

    function _checkPercentage(
        RevenueSplit[] memory revenueSplits
    ) internal pure {
        uint256 _totalPercentage = 0;
        for (uint i = 0; i < revenueSplits.length; i++) {
            _totalPercentage += revenueSplits[i].percentange;
        }
        require(
            _totalPercentage <= 1000,
            "Percentage Calculation is not correct."
        );
    }

    function updatePlatform(address _newPlatform) public onlyPlatform {
        platformAddress = _newPlatform;
    }

    function _addRevenueSplitOfToken(
        uint256 _nftId,
        RevenueSplit[] memory revenueSplits
    ) internal {
        _checkPercentage(revenueSplits);
        delete revenueSplitsOfNFT[_nftId];
        for (uint256 i = 0; i < revenueSplits.length; i++) {
            revenueSplitsOfNFT[_nftId].push(
                RevenueSplit(
                    revenueSplits[i].wallet,
                    revenueSplits[i].percentange,
                    revenueSplits[i].nickname
                )
            );
        }
    }

    function _update(
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts
    ) internal override(ERC1155Upgradeable, ERC1155SupplyUpgradeable) {
        super._update(from, to, ids, amounts);
    }

    function setSecondaryRoyalties(
        uint256 _nftId,
        RevenueSplit memory royalty
    ) public onlyNftCreator(_nftId) onlyNftExist(_nftId) {
        require(royalty.percentange <= 1000, "Secondary royalty percentage too high");
        
        // Update the secondary royalty
        secondaryRoyaltiesOfNFT[_nftId] = RevenueSplit(
            royalty.wallet,
            royalty.percentange,
            royalty.nickname
        );
    }
    

    function royaltyInfo(
        uint256 tokenId,
        uint256 salePrice
    ) external view override returns (address receiver, uint256 royaltyAmount) {
        RevenueSplit memory royalty = secondaryRoyaltiesOfNFT[tokenId];
        
        // Calculate and return only creator's royalty
        uint256 creatorRoyalty = (salePrice * royalty.percentange) / 1000;
        return (royalty.wallet, creatorRoyalty);
    }

    function getSecondaryRoyalties(
        uint256 _nftId
    ) external view returns (RevenueSplit memory) {
        return secondaryRoyaltiesOfNFT[_nftId];
    }

    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(ERC1155Upgradeable, IERC165Upgradeable) returns (bool) {
        return
            interfaceId == type(IERC2981Upgradeable).interfaceId ||
            super.supportsInterface(interfaceId);
    }
}
